#include <stddef.h>
#include <regex.h>
#include "xdiff/xdiff.h"
static int emit(void *p, mmbuffer_t *b, int n) { long *count = (long *)p; int i; for (i = 0; i < n; ++i) *count += b[i].size; return 0; }
int consume_diff(void) { char a[] = "before\n", b[] = "after\n"; mmfile_t left = {a, 7}, right = {b, 6}; xpparam_t xp = {0}; xdemitconf_t cfg = {0}; xdemitcb_t cb = {0}; long count = 0; cb.priv = &count; cb.out_line = emit; return xdl_diff(&left, &right, &xp, &cfg, &cb) == 0 && count > 0; }

#include <stddef.h>
#include <regex.h>
#include <stdlib.h>
#include <string.h>
#include "xdiff/xdiff.h"
int consume_diff(void);
int main(void) { char text[] = "same\n"; mmfile_t base = {text, 5}, left = {text, 5}, right = {text, 5}; xmparam_t xp = {0}; mmbuffer_t out = {0}; int rc = xdl_merge(&base, &left, &right, &xp, &out); int ok = rc == 0 && out.size == 5 && memcmp(out.ptr, text, 5) == 0; free(out.ptr); return ok && consume_diff() ? 0 : 1; }

